import { forbidden } from 'next/navigation'
import { verifyAdmin } from '../lib/auth'
import styles from './admin.module.css'

// Check the session on every request, including when the auth helper changes
// from this mock implementation to a real session provider.
export const dynamic = 'force-dynamic'

export default async function AdminPage() {
  const { isAdmin, session } = await verifyAdmin()

  if (!isAdmin) {
    forbidden()
  }

  return (
    <main className={styles.screen}>
      <section className={styles.card}>
        <span className={styles.eyebrow}>Admin area</span>
        <h1>Admin dashboard</h1>
        <p>Welcome back, {session?.name}.</p>
      </section>
    </main>
  )
}

